    // Memoization (top-down)
    public int climbStairs(int n) {
        int[] memo = new int[n + 1];
        return f(n, memo);
    }

    private int f(int i, int[] memo) {
        if (i <= 1) return 1;
        if (memo[i] != 0) return memo[i]; // already solved
        return (memo[i] = f(i - 1, memo) + f(i - 2, memo));
    }
