        return f(arr.length - 1, k, arr);
    }

    private int f(int i, int k, int[] h) {
        if (i == 0) return 0;
        int best = Integer.MAX_VALUE;
        for (int j = i - 1; j >= Math.max(0, i - k); j--) {
            best = Math.min(best, f(j, k, h) + Math.abs(h[i] - h[j]));
        }
        return best;
    }
}

