class Solution {

    // Tabulation: dp[day][last] = best for days 0..day with 'last' banned on 'day'
    public int maximumPoints(int[][] arr) {
        int n = arr.length;
        int[][] dp = new int[n][4];
        for (int last = 0; last < 4; last++) {
            for (int a = 0; a < 3; a++) {
                if (a != last) dp[0][last] = Math.max(
                    dp[0][last],
                    arr[0][a]
                );
            }
        }
        for (int day = 1; day < n; day++) {
            for (int last = 0; last < 4; last++) {
                for (int a = 0; a < 3; a++) {
                    if (a == last) continue;
                    dp[day][last] = Math.max(
                        dp[day][last],
                        arr[day][a] + dp[day - 1][a]
                    );
                }
            }
        }
        return dp[n - 1][3];
    }
}

