        if (r < 0 || c < 0 || g[r][c] == 1) return 0;
        if (r == 0 && c == 0) return 1;
        if (memo[r][c] != -1) return memo[r][c];
        return (memo[r][c] =
            f(r - 1, c, g, memo) + f(r, c - 1, g, memo));
    }
}

