    public int numDecodings(String s) {
        return f(0, s);
    }

    private int f(int i, String s) {
        if (i == s.length()) return 1; // decoded everything
        if (s.charAt(i) == '0') return 0; // no letter starts with 0
        int ways = f(i + 1, s); // take one digit
        if (
            i + 1 < s.length() &&
