        int best = 0;
        for (int r = 0; r < matrix.length; r++) for (
            int c = 0;
            c < matrix[0].length;
            c++
        ) best = Math.max(best, dfs(r, c, matrix));
        return best;
    }

    private int dfs(int r, int c, int[][] m) {
        int len = 1;
        for (int[] d : DIRS) {
            int nr = r + d[0],
                nc = c + d[1];
            if (
                nr >= 0 &&
                nc >= 0 &&
                nr < m.length &&
                nc < m[0].length &&
                m[nr][nc] > m[r][c]
            ) {
                len = Math.max(len, 1 + dfs(nr, nc, m));
            }
        }
        return len;
    }
}

