class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };

    public int longestIncreasingPath(int[][] matrix) {
        int m = matrix.length,
            n = matrix[0].length,
            best = 0;
        int[][] memo = new int[m][n];
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) best =
            Math.max(best, dfs(r, c, matrix, memo));
        return best;
    }

    private int dfs(int r, int c, int[][] mat, int[][] memo) {
        if (memo[r][c] != 0) return memo[r][c]; // already solved (DAG => reusable)
        int len = 1;
        for (int[] d : DIRS) {
            int nr = r + d[0],
                nc = c + d[1];
            if (
                nr >= 0 &&
                nc >= 0 &&
                nr < mat.length &&
                nc < mat[0].length &&
                mat[nr][nc] > mat[r][c]
            ) {
                len = Math.max(len, 1 + dfs(nr, nc, mat, memo));
            }
        }
        return (memo[r][c] = len);
    }
}

